/// The expected value returned from [`IERC3156FlashBorrower::on_flash_loan`].
pub const BORROWER_CALLBACK_VALUE: [u8; 32] = keccak_const::Keccak256::new()
    .update("ERC3156FlashBorrower.onFlashLoan".as_bytes())
    .finalize();

