/// Interface for a UUPS (Universal Upgradeable Proxy Standard) upgradeable
/// contract.
#[allow(missing_docs)]
#[public]
pub trait IUUPSUpgradeable: IErc1822Proxiable {
    /// Returns the version of the upgrade interface of the contract.
    ///
    /// NOTE: Make sure to set proper selector in order to make the function
    /// compatible with Solidity version.
    ///
    /// ```rust,ignore
    /// #[selector(name = "UPGRADE_INTERFACE_VERSION")]
    /// fn upgrade_interface_version(&self) -> String {
    ///     self.uups.upgrade_interface_version()
    /// }
    /// ```
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    fn upgrade_interface_version(&self) -> String;

    /// Upgrade the implementation of the proxy to `new_implementation`, and
    /// subsequently execute the function call encoded in `data`.
    ///
    /// Note: This primitive does not include an authorization mechanism. To
    /// restrict who can upgrade, enforce access control in your contract
    /// before delegating to this function.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `new_implementation` - The address of the new implementation contract.
    /// * `data` - Additional data to be passed to the new implementation.
    ///
    /// # Errors
    ///
    /// * [`Error::UnauthorizedCallContext`] - If the call is not made through a
    ///   valid proxy context.
    /// * [`Error::InvalidImplementation`] - If the new implementation address
    ///   is invalid or doesn't implement the required interface.
    /// * [`Error::UnsupportedProxiableUUID`] - If the new implementation
    ///   returns an unsupported UUID.
    /// * [`Error::NonPayable`] - If the upgrade function receives ETH but is
    ///   not designed to handle it.
    /// * [`Error::EmptyCode`] - If there's no code at the new implementation
    ///   address.
    /// * [`Error::FailedCall`] - If the [`stylus_sdk::call::delegate_call`] to the
    ///   new implementation fails.
    /// * [`Error::FailedCallWithReason`] - If the
    ///   [`stylus_sdk::call::delegate_call`] fails with a specific reason.
    ///
    /// # Events
    ///
    /// * [`crate::proxy::erc1967::Upgraded`]: Emitted when the implementation
    ///   is upgraded.
    ///
    /// [delegate_call]: stylus_sdk::call::delegate_call
    fn upgrade_to_and_call(
        &mut self,
        new_implementation: Address,
        data: Bytes,
    ) -> Result<(), Vec<u8>>;
}

/// A contract that implements the UUPS (Universal Upgradeable Proxy Standard)
/// pattern for upgradeable contracts.
///
/// # Overview
///
/// This implementation provides upgradeability functionality for proxy
/// contracts while maintaining storage compatibility across upgrades. It
/// follows the UUPS pattern defined in [EIP-1822], where the upgrade
/// logic is included in the implementation contract rather than the proxy.
///
/// This Stylus version contains some architectural differences compared to
/// Solidity's implementation, while maintaining the same security model and
/// upgrade flow.
///
/// # Design Rationale & Differences from Solidity
///
/// ## Storage-based Context Detection
///
/// Solidity often relies on an `immutable` self-address to detect context. In
/// Stylus, this contract uses a boolean `logic_flag` stored in a dedicated
/// slot:
/// - When executing directly on the implementation, the constructor has set
///   `logic_flag = true` in the implementation’s storage.

output.text:
    ///
    /// Returns a boolean value indicating whether the operation succeeded.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `receiver` - The receiver of the flash loan. Should implement the
    ///   [`IERC3156FlashBorrower::on_flash_loan`] interface.
    /// * `token` - The token to be flash loaned. Only this contract's address
    ///   is supported.
    /// * `value` - The amount of tokens to be loaned.
    /// * `data` - Arbitrary data that is passed to the receiver.
    ///
    /// # Errors
    ///
    /// * [`Error::ExceededMaxLoan`] - If the `value` is greater than the value
    ///   returned by [`IErc3156FlashLender::max_flash_loan`].
    /// * [`Error::UnsupportedToken`] - If `token` is not supported.
    /// * [`Error::InvalidReceiver`] - If the `token` address is not a contract
    ///   , the contract fails to execute the call, or the receiver does not
    ///   return [`BORROWER_CALLBACK_VALUE`].
    ///
    /// # Events
    ///
    /// * [`erc20::Transfer`].
    /// * [`erc20::Approval`].
    ///
    /// # Panics
    ///
    /// * If the new (temporary) total supply exceeds [`U256::MAX`].
    /// * If the sum of the loan value and fee exceeds the maximum value of
    ///   [`U256::MAX`].
    fn flash_loan(
        &mut self,
        receiver: Address,
        token: Address,
        value: U256,
        data: Bytes,
    ) -> Result<bool, Self::Error>;
}

impl Erc20FlashMint {
    /// See [`IErc3156FlashLender::max_flash_loan`].
    #[must_use]
    pub fn max_flash_loan(&self, token: Address, erc20: &erc20::Erc20) -> U256 {
        if token == self.vm().contract_address() {
            U256::MAX - erc20.total_supply()
        } else {
            U256::MIN
        }
    }

    /// See [`IErc3156FlashLender::flash_fee`].
    #[allow(clippy::missing_errors_doc)]
    pub fn flash_fee(
        &self,
        token: Address,
        _value: U256,
    ) -> Result<U256, Error> {
        if token == self.vm().contract_address() {
            Ok(self.flash_fee_value.get())
        } else {
            Err(Error::UnsupportedToken(ERC3156UnsupportedToken { token }))
        }
    }

    // This function can reenter, but it doesn't pose a risk because it always
    // preserves the property that the amount minted at the beginning is always
    // recovered and burned at the end, or else the entire function will revert.
    /// See [`IErc3156FlashLender::flash_loan`].
    #[allow(clippy::missing_panics_doc, clippy::missing_errors_doc)]
    pub fn flash_loan(
        &mut self,
        receiver: Address,
        token: Address,
        value: U256,
        data: &Bytes,
        erc20: &mut Erc20,
    ) -> Result<bool, Error> {
        let max_loan = self.max_flash_loan(token, erc20);
        if value > max_loan {
            return Err(Error::ExceededMaxLoan(ERC3156ExceededMaxLoan {
                max_loan,
            }));
        }

        let fee = self.flash_fee(token, value)?;
        if self.vm().code_size(receiver) == 0 {
            return Err(Error::ERC3156InvalidReceiver(
                ERC3156InvalidReceiver { receiver },
            ));
        }
        erc20._mint(receiver, value)?;
        let loan_receiver = IERC3156FlashBorrower::new(receiver);
        let initiator = self.vm().msg_sender();
        let call = Call::new_mutating(self);
        let loan_return = loan_receiver
            .on_flash_loan(
                self.vm(),
                call,
                initiator,
                token,
                value,
                fee,
                data.to_vec().into(),
            )
            .map_err(|_| {
                Error::ERC3156InvalidReceiver(ERC3156InvalidReceiver {
                    receiver,
                })
            })?;
        if loan_return != BORROWER_CALLBACK_VALUE {
            return Err(Error::ERC3156InvalidReceiver(
                ERC3156InvalidReceiver { receiver },
            ));
        }

        let allowance = value
            .checked_add(fee)
            .expect("allowance should not exceed `U256::MAX`");
        erc20._spend_allowance(
            receiver,
            self.vm().contract_address(),
            allowance,
        )?;

        let flash_fee_receiver = self.flash_fee_receiver_address.get();

        if fee.is_zero() || flash_fee_receiver.is_zero() {
            erc20._burn(receiver, allowance)?;
        } else {
            erc20._burn(receiver, value)?;
            erc20._transfer(receiver, flash_fee_receiver, fee)?;
        }

        Ok(true)
    }
}

