/// The expected value returned from [`IErc1155Receiver::on_erc1155_received`].
pub const SINGLE_TRANSFER_FN_SELECTOR: B32 = B32::new(function_selector!(
    "onERC1155Received",
    Address,
    Address,
    U256,
