#[openzeppelin_stylus_proc::vm_test]
fn flash_loan_burns_the_loan_and_transfers_the_fee(
    contract: Contract<Erc20FlashMintTestExample>,
    alice: Address,
    bob: Address,
    receiver: Address,
) {
    let amount = uint!(100_U256);
    let fee = uint!(7_U256);
    let data = vec![1, 2, 3];
    contract
        .sender(alice)
        .erc20_flash_mint
        .flash_fee_value
        .set(fee);
    contract
        .sender(alice)
        .erc20_flash_mint
        .flash_fee_receiver_address
        .set(bob);
    contract
        .sender(alice)
        .erc20
        ._mint(receiver, fee)
        .expect("should seed receiver with fee tokens");
    contract
        .sender(alice)
        .erc20
        ._approve(
            receiver,
            contract.address(),
            amount + fee,
            false,
        )
        .expect("should approve full repayment");
    mock_borrower_callback(
        &contract,
        receiver,
        alice,
        contract.address(),
        amount,
        fee,
        data.clone(),
        Ok(BORROWER_CALLBACK_VALUE.to_vec()),
    );

    assert!(contract
        .sender(alice)
        .flash_loan(receiver, contract.address(), amount, data.into())
        .expect("valid borrower should repay the loan"));
    assert_eq!(U256::ZERO, contract.sender(alice).erc20.balance_of(receiver));
    assert_eq!(fee, contract.sender(alice).erc20.balance_of(bob));
    assert_eq!(fee, contract.sender(alice).erc20.total_supply());
    assert_eq!(U256::ZERO, contract.sender(alice).erc20.allowance(receiver, contract.address()));
}

