        .flash_loan(alice, contract.address(), U256::MAX, vec![0, 1].into())
        .expect_error("should return Error::ExceededMaxLoan");

    assert!(matches!(
        err,
        Error::ExceededMaxLoan(ERC3156ExceededMaxLoan { max_loan })
            if max_loan == U256::MAX - initial_supply
    ));
}

