+    fn erc20_implementation_exposes_the_full_public_interface(
+        erc20: Contract<Erc20Example>,
+        alice: Address,
+        bob: Address,
+        operator: Address,
+    ) {
+        let initial_supply = U256::from(20);
+        erc20
