 14	/// This trait provides a fallback function that delegates all calls to another
 15	/// contract using the Stylus [`stylus_sdk::call::delegate_call`] function. We
 16	/// refer to the second contract as the _implementation_ behind the proxy, and
 17	/// it has to be specified by overriding the virtual [`IProxy::implementation`]
 18	/// function.
 19	///
 20	/// Additionally, delegation to the implementation can be triggered manually
 21	/// through the [`IProxy::do_fallback`] function, or to a different contract
 22	/// through the [`IProxy::delegate`] function.
 23	///
 24	/// The success and return data of the delegated call will be returned back
 25	/// to the caller of the proxy.
 26	///
 27	/// # Safety
 28	///
 29	/// This trait is unsafe to implement because it uses the `unsafe`
 30	/// [`stylus_sdk::call::delegate_call`] function.
 31	///
 32	/// The caller must ensure that `self` is a valid contract storage context.
 33	///
 34	/// The caller must ensure that the implementation contract is a valid contract
 35	/// address.
 36	///
 37	pub unsafe trait IProxy:
 38	    TopLevelStorage + HostAccess<Host = VM> + Sized
 39	{
 40	    /// Delegates the current call to [`IProxy::implementation`].
 41	    ///
 42	    /// This function does not return to its internal call site, it will
 43	    /// return directly to the external caller.
 44	    ///
 45	    /// # Arguments
 46	    ///
 47	    /// * `&mut self` - Write access to the contract's state.
 48	    /// * `implementation` - The address of the implementation contract.
 49	    /// * `calldata` - The calldata to delegate to the implementation contract.
 50	    ///
 51	    /// # Errors
 52	    ///
 53	    /// Returns an [`Error`] if the delegate call fails. This
 54	    /// error may represent:
 55	    /// * A revert from the implementation contract, containing the revert data.
 56	    /// * Failure to decode the return data from the implementation contract.
 57	    /// * Other low-level call failures as defined by the Stylus SDK.
 58	    #[allow(clippy::missing_safety_doc)]
 59	    unsafe fn delegate(
 60	        &mut self,
 61	        implementation: Address,
 62	        calldata: &[u8],
 63	    ) -> Result<Vec<u8>, Error> {
 64	        let host = (*self.vm()).clone();
 65	        call::delegate_call(
 66	            &host,
 67	            Call::new_mutating(self),
 68	            implementation,
 69	            calldata,
 70	        )
 71	    }
 72	
 73	    /// This is a virtual function that should be overridden so it
 74	    /// returns the address to which the fallback function and
 75	    /// [`IProxy::do_fallback`] should delegate.
 76	    ///
 77	    /// # Arguments
 78	    ///
 79	    /// * `&self` - Read access to the contract's state.
 80	    ///
 81	    /// # Errors
 82	    ///
 83	    /// Implementing contracts should define their own error types for this
 84	    /// function. Typically, errors may include:
 85	    /// * The implementation address is invalid (e.g., not a contract).
 86	    /// * The implementation is not a contract.
 87	    ///
 88	    /// The error should be encoded as a `Vec<u8>`.
 89	    fn implementation(&self) -> Result<Address, Vec<u8>>;
 90	
 91	    /// Fallback function that delegates calls to the address returned
 92	    /// by [`IProxy::implementation`]. Will run if no other function in the
 93	    /// contract matches the call data.
 94	    ///
 95	    /// # Arguments
 96	    ///
 97	    /// * `&mut self` - Write access to the contract's state.
 98	    /// * `calldata` - The calldata to delegate to the implementation contract.
 99	    ///
100	    /// # Errors
101	    ///
102	    /// Implementing contracts should define their own error types for this
103	    /// function. Typically, errors may include:
104	    /// * The implementation address is invalid (e.g., not a contract).
105	    /// * The implementation is not a contract.
106	    /// * The implementation reverted with a reason.
107	    ///
108	    /// The error should be encoded as a `Vec<u8>`.
109	    #[allow(clippy::missing_safety_doc)]
110	    unsafe fn do_fallback(
111	        &mut self,
112	        calldata: &[u8],
113	    ) -> Result<Vec<u8>, Vec<u8>> {
114	        Ok(self.delegate(self.implementation()?, calldata)?)
115	    }
116	}
