 103	/// An [`Erc721Consecutive`] error.
 104	#[derive(SolidityError, Debug)]
 105	pub enum Error {
 106	    /// Indicates that an address can't be an owner.
 107	    /// For example, [`Address::ZERO`] is a forbidden owner in [`Erc721`].
 108	    /// Used in balance queries.
 109	    InvalidOwner(ERC721InvalidOwner),
 110	    /// Indicates a `token_id` whose `owner` is the zero address.
 111	    NonexistentToken(ERC721NonexistentToken),
 112	    /// Indicates an error related to the ownership over a particular token.
 113	    /// Used in transfers.
 114	    IncorrectOwner(ERC721IncorrectOwner),
 115	    /// Indicates a failure with the token `sender`. Used in transfers.
 116	    InvalidSender(ERC721InvalidSender),
 117	    /// Indicates a failure with the token `receiver`. Used in transfers.
 118	    InvalidReceiver(ERC721InvalidReceiver),
 119	    /// Indicates a failure with the token `receiver`, with the reason
 120	    /// specified by it.
 121	    InvalidReceiverWithReason(InvalidReceiverWithReason),
 122	    /// Indicates a failure with the `operator`’s approval. Used in transfers.
 123	    InsufficientApproval(ERC721InsufficientApproval),
 124	    /// Indicates a failure with the `approver` of a token to be approved. Used
 125	    /// in approvals.
 126	    InvalidApprover(ERC721InvalidApprover),
 127	    /// Indicates a failure with the `operator` to be approved. Used in
 128	    /// approvals.
 129	    InvalidOperator(ERC721InvalidOperator),
 130	    /// A value was attempted to be inserted into a past checkpoint.
 131	    CheckpointUnorderedInsertion(CheckpointUnorderedInsertion),
 132	    /// Batch mint is restricted to the constructor.
 133	    /// Any batch mint not emitting the [`Transfer`] event outside of
 134	    /// the constructor is non ERC-721 compliant.
 135	    ForbiddenBatchMint(ERC721ForbiddenBatchMint),
 136	    /// Exceeds the max amount of mints per batch.
 137	    ExceededMaxBatchMint(ERC721ExceededMaxBatchMint),
 138	    /// Individual minting is not allowed.
 139	    ForbiddenMint(ERC721ForbiddenMint),
 140	    /// Batch burn is not supported.
 141	    ForbiddenBatchBurn(ERC721ForbiddenBatchBurn),
 142	}
