 144	impl From<erc721::Error> for Error {
 145	    fn from(value: erc721::Error) -> Self {
 146	        match value {
 147	            erc721::Error::InvalidOwner(e) => Error::InvalidOwner(e),
 148	            erc721::Error::NonexistentToken(e) => Error::NonexistentToken(e),
 149	            erc721::Error::IncorrectOwner(e) => Error::IncorrectOwner(e),
 150	            erc721::Error::InvalidSender(e) => Error::InvalidSender(e),
 151	            erc721::Error::InvalidReceiver(e) => Error::InvalidReceiver(e),
 152	            erc721::Error::InvalidReceiverWithReason(e) => {
 153	                Error::InvalidReceiverWithReason(e)
 154	            }
 155	            erc721::Error::InsufficientApproval(e) => {
 156	                Error::InsufficientApproval(e)
 157	            }
 158	            erc721::Error::InvalidApprover(e) => Error::InvalidApprover(e),
 159	            erc721::Error::InvalidOperator(e) => Error::InvalidOperator(e),
 160	        }
 161	    }
