 234	    fn safe_transfer_from_with_data(
 235	        &mut self,
 236	        from: Address,
 237	        to: Address,
 238	        token_id: U256,
 239	        data: Bytes,
 240	    ) -> Result<(), Error> {
 241	        self.transfer_from(from, to, token_id)?;
 242	        Ok(self.erc721._check_on_erc721_received(
 243	            self.vm().msg_sender(),
 244	            from,
 245	            to,
 246	            token_id,
 247	            &data,
