 251	    fn transfer_from(
 252	        &mut self,
 253	        from: Address,
 254	        to: Address,
 255	        token_id: U256,
 256	    ) -> Result<(), Error> {
 257	        if to.is_zero() {
 258	            return Err(erc721::Error::InvalidReceiver(
 259	                ERC721InvalidReceiver { receiver: Address::ZERO },
 260	            )
 261	            .into());
 262	        }
 263	
 264	        // Setting an "auth" argument enables the `_is_authorized` check which
 265	        // verifies that the token exists (`!from.is_zero()`). Therefore, it is
 266	        // not needed to verify that the return value is not 0 here.
 267	        let previous_owner =
 268	            self._update(to, token_id, self.vm().msg_sender())?;
 269	        if previous_owner != from {
 270	            return Err(erc721::Error::IncorrectOwner(ERC721IncorrectOwner {
 271	                sender: from,
 272	                token_id,
 273	                owner: previous_owner,
 274	            })
 275	            .into());
 276	        }
 277	        Ok(())
 278	    }
