 265	        // verifies that the token exists (`!from.is_zero()`). Therefore, it is
 266	        // not needed to verify that the return value is not 0 here.
 267	        let previous_owner =
 268	            self._update(to, token_id, self.vm().msg_sender())?;
 269	        if previous_owner != from {
 270	            return Err(erc721::Error::IncorrectOwner(ERC721IncorrectOwner {
 271	                sender: from,
 272	                token_id,
 273	                owner: previous_owner,
